using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Imaging;
using System.Linq;
using System.Windows.Forms;

namespace ScopeMaker {
public partial class MainWindow {
 static void EditCheck(bool ok,string name,List<string> results){if(!ok)throw new Exception("FAIL: "+name);results.Add("PASS: "+name);}
 public static void EditingChecks(List<string> results){
  var line=new Part{X=-1,Y=0,X2=1,Y2=0,Original="line { line:p4=-1,0,1,0; radialAngle:r=12; }",Mils=false,StrokeWidth=2};var cut=EraserGeometry.CutLine(line,-.1,-.1,.1,.1);
  EditCheck(cut.Count==2&&Math.Abs(cut[0].X2+.1)<1e-9&&Math.Abs(cut[1].X-.1)<1e-9&&cut[0].Original==line.Original&&cut[1].StrokeWidth==2,"Eraser splits lines at brush edges and retains native metadata",results);
  var arcCut=EraserGeometry.CutCircle(new Part{Kind="circle",X=0,Y=0,Size=1},.4,-.1,.6,.1);EditCheck(arcCut.Count>0&&arcCut.Sum(p=>p.End-p.Start)<350&&arcCut.Sum(p=>p.End-p.Start)>330,"Eraser removes a local circle segment while retaining editable arcs",results);
  var quad=new Part{Kind="quad",Original="quad { tl:p2=-0.5,-0.5; tr:p2=0.5,-0.5; br:p2=0.5,0.5; bl:p2=-0.5,0.5; radialAngle:r=17; }"};var quadCut=EraserGeometry.CutQuad(quad,-.1,-.1,.1,.1);EditCheck(quadCut.Count==4&&quadCut.All(p=>p.Original.Contains("radialAngle"))&&Blk.Import(Blk.Export(new Project{Parts=quadCut})).Parts.Count==4,"Eraser supports imported BLK quads and preserves their native fields",results);
  var tiles=EraserGeometry.Subtract(new[]{-.5,-.5,.5,.5},-.1,-.1,.1,.1);EditCheck(tiles.Count==4&&Math.Abs(tiles.Sum(t=>(t[2]-t[0])*(t[3]-t[1]))-.96)<1e-9,"Eraser subtracts only the touched area of an image tile",results);
  bool touched;var image=new Part{Kind="image",X=.2,Y=-.1,Size=2,Tiles=new List<double[]>{new[]{-.5,-.5,.5,.5}}};var erased=EraserGeometry.Apply(new[]{image},.2,-.1,.1,500,1,out touched);
  EditCheck(touched&&erased.Count==1&&erased[0].Tiles.Count==4&&image.Tiles.Count==1&&erased[0].Size==2,"Image erasure preserves grouping, position, scale and original undo data",results);
  var project=new Project{Parts=erased};var imported=Blk.Import(Blk.Export(project));EditCheck(imported.Parts.Count==4&&!imported.Parts.Any(p=>{var n=Blk.Parse(p.Original)[0];var a=Blk.Values(n.Get("tl","0,0"),2);var b=Blk.Values(n.Get("br","0,0"),2);return .2>a[0]&&.2<b[0]&&-.1>a[1]&&-.1<b[1];}),"Erased image holes survive BLK export and reimport",results);
  var mils=new Part{Kind="line",X=-10,X2=10,Mils=true};var milCut=EraserGeometry.Apply(new[]{mils},0,0,.04,400,1,out touched);EditCheck(touched&&milCut.Count==2&&Math.Abs(milCut[0].X2+1)<.04,"Eraser maps screen brush to thousandth coordinates",results);
  using(var w=new MainWindow()){
   w.Show();Application.DoEvents();w.SetDocument(new Project{Parts=new List<Part>{new Part{X=-.8,X2=.8}}},"");int cx=w.canvas.Width/2,cy=w.canvas.Height/2;w.drawingTool.SelectedIndex=7;
   w.CanvasDown(w.canvas,new MouseEventArgs(MouseButtons.Left,1,cx-45,cy,0));w.CanvasMove(w.canvas,new MouseEventArgs(MouseButtons.Left,0,cx+45,cy,0));w.CanvasUp(w.canvas,new MouseEventArgs(MouseButtons.Left,1,cx+45,cy,0));
   EditCheck(w.Doc.Parts.Count==2&&w.undo.Count==1&&w.dirty,"Swept eraser gesture leaves no gaps and creates exactly one undo step",results);w.Undo(false);EditCheck(w.Doc.Parts.Count==1&&!w.dirty,"Undo restores the entire erased stroke and saved-state baseline",results);w.Undo(true);EditCheck(w.Doc.Parts.Count==2,"Redo reapplies the erased stroke",results);
   string before=w.json.Serialize(w.Doc);int count=w.undo.Count;w.CanvasDown(w.canvas,new MouseEventArgs(MouseButtons.Left,1,cx-120,cy,0));w.CancelDrawing();EditCheck(w.json.Serialize(w.Doc)==before&&w.undo.Count==count,"Esc or capture loss cancels eraser edits without adding history",results);
   w.SetDocument(new Project{Parts=new List<Part>{image}},"");w.drawingTool.SelectedIndex=0;double size=w.Selected.Size;w.ScaleSelectedImage(1.1);w.ScaleSelectedImage(1/1.1);EditCheck(Math.Abs(w.Selected.Size-size)<1e-10&&w.Selected.X==.2&&w.Selected.Tiles.Count==1,"Image scaling buttons preserve center and geometry",results);
   var box=w.ImageBounds(w.Selected);var handle=new Point((int)box.Right,(int)box.Bottom);var center=w.Screen(w.Selected.X,w.Selected.Y,false,w.canvas.ClientRectangle);w.CanvasDown(w.canvas,new MouseEventArgs(MouseButtons.Left,1,handle.X,handle.Y,0));w.CanvasMove(w.canvas,new MouseEventArgs(MouseButtons.Left,0,(int)(center.X+(handle.X-center.X)*1.5),(int)(center.Y+(handle.Y-center.Y)*1.5),0));w.CanvasUp(w.canvas,new MouseEventArgs(MouseButtons.Left,1,(int)(center.X+(handle.X-center.X)*1.5),(int)(center.Y+(handle.Y-center.Y)*1.5),0));EditCheck(w.Selected.Size>size*1.45&&w.Selected.Size<size*1.55,"Canvas corner handle scales images proportionally",results);w.Undo(false);EditCheck(Math.Abs(w.Selected.Size-size)<1e-9,"Image handle resize is a single undoable edit",results);w.dirty=false;w.Close();
  }
  using(var bitmap=new Bitmap(1024,1024)){using(var g=Graphics.FromImage(bitmap)){g.Clear(Color.White);g.FillRectangle(Brushes.Black,511,0,1,1024);}using(var converted=ImageConverter.Convert(bitmap,new ImageSettings{Resolution=1024,Trim=false})){EditCheck(converted.Width==1024&&converted.Tiles.Count==1&&Math.Abs(converted.Tiles[0][2]-converted.Tiles[0][0]-1.0/1024)<1e-9,"High resolution conversion preserves single-pixel 1024px strokes",results);}}
  using(var bitmap=new Bitmap(256,256)){using(var g=Graphics.FromImage(bitmap)){g.Clear(Color.White);for(int y=0;y<256;y+=2)for(int x=0;x<256;x+=2)g.FillRectangle(Brushes.Black,x,y,1,1);}using(var fitted=ImageConverter.Convert(bitmap,new ImageSettings{Resolution=256,MaxTiles=1000})){EditCheck(!fitted.Limited&&fitted.Tiles.Count<=1000&&fitted.Reduced&&fitted.Tiles.Count>0,"Complex images automatically fit the remaining project geometry budget",results);}using(var limited=ImageConverter.Convert(bitmap,new ImageSettings{Resolution=256,MaxTiles=1000,FitBudget=false})){EditCheck(limited.Limited,"Disabling automatic detail reduction reports overflow without accepting partial geometry",results);}}
  using(var bitmap=new Bitmap(256,128)){using(var g=Graphics.FromImage(bitmap)){for(int x=0;x<256;x++){int shade=160+x*80/256;using(var pen=new Pen(Color.FromArgb(shade,shade,shade)))g.DrawLine(pen,x,0,x,127);}g.FillRectangle(Brushes.Black,100,0,2,128);}using(var result=ImageConverter.Convert(bitmap,new ImageSettings{Resolution=256,Adaptive=true,Trim=false})){EditCheck(result.Preview.GetPixel(10,60).R==17&&result.Preview.GetPixel(100,60).R==92,"Local threshold separates ink from uneven paper illumination",results);}}
  using(var bitmap=new Bitmap(4096,2304)){using(var g=Graphics.FromImage(bitmap)){g.Clear(Color.White);g.DrawEllipse(Pens.Black,100,100,3000,2000);}using(var prepared=ImageSource.Prepare(bitmap))using(var converted=ImageConverter.Convert(prepared,new ImageSettings{Resolution=2048})){EditCheck(converted.ActualResolution==2048&&!converted.Limited&&converted.Tiles.Count>0,"Large 4096px artwork converts at 2048px within the geometry budget",results);}bool canceled=false;try{using(var r=ImageConverter.Convert(bitmap,new ImageSettings(),delegate{return true;})){} }catch(OperationCanceledException){canceled=true;}EditCheck(canceled,"Background image conversion supports cancellation",results);}
  using(var input=FeatureTests.Fixture())using(var dialog=new ImageImportDialog(input)){dialog.Show();Application.DoEvents();dialog.WaitForPreview();EditCheck(!dialog.PreviewBusy,"Asynchronous import preview finishes without blocking normal window events",results);var combo=Descendants(dialog).OfType<ComboBox>().First(c=>c.Items.Cast<object>().Any(v=>v.ToString()=="2048"));combo.SelectedItem=2048;combo.SelectedItem=128;EditCheck(dialog.PreviewBusy&&!Descendants(dialog).OfType<Button>().First(b=>b.Text==L.T("Добавить")).Enabled,"Changing import settings immediately prevents accepting a stale preview",results);dialog.WaitForPreview();EditCheck(!dialog.PreviewBusy&&Descendants(dialog).OfType<Button>().First(b=>b.Text==L.T("Добавить")).Enabled,"Latest import settings win after rapid changes",results);dialog.Close();}
 }
 public void EditingScreenshot(string path,bool eraser){using(var input=FeatureTests.Fixture())using(var converted=ImageConverter.Convert(input,new ImageSettings{Resolution=1024})){SetDocument(new Project{Title=L.T("Рисунок"),Parts=new List<Part>{new Part{Kind="image",Name=L.T("Рисунок"),X=0,Y=0,Size=1.4,Tiles=converted.Tiles}}},"");drawingTool.SelectedIndex=eraser?7:0;Show();Application.DoEvents();showEraser=eraser;eraseHover=new Point(canvas.Width/2,canvas.Height/2);using(var bmp=new Bitmap(Width,Height)){DrawToBitmap(bmp,new Rectangle(0,0,Width,Height));bmp.Save(path);}dirty=false;Close();}}
}
}
